BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_DDI_VRF (ID CHAR(36) PRIMARY KEY,ORGANIZATION_ID CHAR(36) NOT NULL,CODE VARCHAR2(64) NOT NULL,DISPLAY_NAME VARCHAR2(160) NOT NULL,ROUTE_DISTINGUISHER VARCHAR2(128),LIFECYCLE_STATUS VARCHAR2(16) NOT NULL,VERSION NUMBER(19) NOT NULL,CREATED_AT TIMESTAMP WITH TIME ZONE NOT NULL,UPDATED_AT TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT UQ_DDI_VRF_ORG_CODE UNIQUE(ORGANIZATION_ID,CODE))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE != -955 THEN RAISE; END IF; END;
